<?php require __DIR__.'/../bootstrap.php'; require_admin();
$pdo=db(); $counts=[]; foreach(['total'=>'','new'=>"WHERE status='new'",'progress'=>"WHERE status IN ('triaged','in_progress')",'resolved'=>"WHERE status IN ('resolved','closed')"] as $k=>$where){$counts[$k]=(int)$pdo->query('SELECT COUNT(*) c FROM bug_reports '.($where?:''))->fetch()['c'];}
$q=trim($_GET['q']??'');$status=$_GET['status']??'';$severity=$_GET['severity']??'';$where=[];$args=[];if($q!==''){$where[]='(title LIKE ? OR description LIKE ? OR reporter_email LIKE ?)';$args=["%$q%","%$q%","%$q%"];}if(in_array($status,['new','triaged','in_progress','resolved','closed'],true)){$where[]='status=?';$args[]=$status;}if(in_array($severity,['low','medium','high','critical'],true)){$where[]='severity=?';$args[]=$severity;}$sql='SELECT * FROM bug_reports'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC';$stmt=$pdo->prepare($sql);$stmt->execute($args);$reports=$stmt->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard — IssuePilot</title><link rel="stylesheet" href="../assets/style.css"></head><body class="adminbody"><header class="adminnav"><a class="brand" href="../index.php"><span class="mark">↗</span> IssuePilot</a><div style="display:flex;gap:14px;align-items:center"><span class="muted" style="font-size:13px">Admin workspace</span><a class="btn" href="logout.php">Sign out</a></div></header><main class="adminmain"><div class="adminhead"><div><h1>Bug reports</h1><div class="muted" style="margin-top:5px">Review, triage and resolve incoming reports.</div></div><a class="btn purple" href="../submit.php">Submit a test report</a></div><div class="stats"><div class="stat"><b><?=$counts['total']?></b><span>Total reports</span></div><div class="stat"><b><?=$counts['new']?></b><span>New</span></div><div class="stat"><b><?=$counts['progress']?></b><span>In progress</span></div><div class="stat"><b><?=$counts['resolved']?></b><span>Resolved / closed</span></div></div><form class="toolbar" method="get"><input class="input" name="q" value="<?=e($q)?>" placeholder="Search title, description or email"><select class="select" name="status"><option value="">All statuses</option><?php foreach(['new','triaged','in_progress','resolved','closed'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=ucwords(str_replace('_',' ',$s))?></option><?php endforeach;?></select><select class="select" name="severity"><option value="">All severity</option><?php foreach(['low','medium','high','critical'] as $s):?><option value="<?=$s?>" <?=$severity===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select><button class="btn primary">Filter</button></form><div class="tablewrap"><table class="table"><thead><tr><th>Report</th><th>Severity</th><th>Status</th><th>Reporter</th><th>Created</th><th></th></tr></thead><tbody><?php if(!$reports):?><tr><td colspan="6" class="muted">No reports found.</td></tr><?php else: foreach($reports as $r):?><tr><td><strong>#<?=e((string)$r['id'])?> · <?=e($r['title'])?></strong><div class="muted" style="margin-top:4px;max-width:480px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis"><?=e($r['description'])?></div></td><td class="sev-<?=e($r['severity'])?>"><?=ucfirst($r['severity'])?></td><td><span class="badge b-<?=e($r['status'])?>"><?=ucwords(str_replace('_',' ',$r['status']))?></span></td><td><?=e($r['reporter_email'] ?: 'Anonymous')?></td><td><?=e(date('M j, Y · H:i',strtotime($r['created_at'])))?></td><td><a class="btn" href="view.php?id=<?=$r['id']?>">Open</a></td></tr><?php endforeach; endif;?></tbody></table></div></main></body></html>
